{
  "gate_token": "dOSZTuTTrxZ39gprsWe-6Q",
  "title": "The Mirror Road Home",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "Mara unrolls a map of the ruined royal city.",
      "visual_description": "A windswept hill at dusk overlooks a broken skyline of toppled spires; an ink-stained coated figure with a brass compass pins down a crackling map weighted with stones.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "The oracle lamp sparks awake with a warning.",
      "visual_description": "Close-up of an oil lamp on the map, its single eye-flame flaring orange, casting long shadows across the parchment streets.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 3,
      "caption": "The tin fox is wound for the scouting run.",
      "visual_description": "Gloved hands twist a brass key in the tail of a small metal fox with blue glass eyes, gears ticking visibly along its flank.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 4,
      "caption": "Glass Diver arrives by stepping out of a puddle.",
      "visual_description": "A figure in a clear diving helmet emerges waist-deep from a shallow rain puddle, coat shimmering with reflected broken city lights.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 5,
      "caption": "They approach the cracked castle gates.",
      "visual_description": "Massive iron gates hang half-broken under a torn royal banner; four small figures stand dwarfed at the threshold beneath crumbling stone lions.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 6,
      "caption": "The tin fox slips through to scout the courtyard.",
      "visual_description": "Through a narrow gap in the gate, the clockwork fox darts across moss-cracked flagstones; faded banners ripple above empty armor stands.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 7,
      "caption": "An armored patrol clanks past in the rubble.",
      "visual_description": "From a low angle behind a fallen column, suits of plate armor march in single file; the tin fox crouches in shadow, blue eyes dim to hide its glow.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 8,
      "caption": "The lamp warns of the cursed tower ahead.",
      "visual_description": "A leaning black tower glows with greenish runes; the oracle lamp hovers near Mara's shoulder, its flame-eye narrowed in alarm.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 9,
      "caption": "Glass Diver dives through a tall stained window.",
      "visual_description": "Mid-leap, the coated rescuer plunges headfirst into a stained-glass pane that ripples like water, fragments of colored light splashing outward.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 10,
      "caption": "Rumors of a dragon echo from the smoke.",
      "visual_description": "Distant plumes of smoke rise over rooftops shaped like a long serpentine shadow; Mara shields her eyes, the tin fox tense at her boot.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 11,
      "caption": "They find the sleeping tax collector slumped at his desk.",
      "visual_description": "Inside a dusty records office, a plump official snores on a ledger pillow, stamped papers stuck to his sleeves, a key ring dangling from his belt.",
      "characters": ["mara_the_cartographer", "glass_diver", "sleeping_tax_collector"]
    },
    {
      "scene_number": 12,
      "caption": "The lamp reads a hidden seal on his ledger.",
      "visual_description": "The oracle lamp leans low over an open ledger, its flame illuminating a wax seal that maps the tower's inner stairs.",
      "characters": ["oracle_lamp", "sleeping_tax_collector", "mara_the_cartographer"]
    },
    {
      "scene_number": 13,
      "caption": "A magic door demands a reflection to open.",
      "visual_description": "A silver-rimmed door set in stone shows no handle, only a mirror surface rippling like mercury; Glass Diver raises a gloved palm toward it.",
      "characters": ["glass_diver", "oracle_lamp"]
    },
    {
      "scene_number": 14,
      "caption": "Glass Diver swims through and unlatches it from inside.",
      "visual_description": "Split-panel view: on one side the coat tail vanishes into the mirror; on the other, the diver tumbles into a vaulted prison chamber lit by torchlight.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 15,
      "caption": "The tin fox leads them through tilted hallways.",
      "visual_description": "Crooked corridors with banners hanging sideways; the little metal fox trots ahead, its key-wind tail clicking, casting a thin blue beam from its eyes.",
      "characters": ["tin_fox", "mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 16,
      "caption": "They drag the sleeping tax collector toward the bridge.",
      "visual_description": "Mara and Glass Diver haul the snoring official by his arms across cracked palace tiles, his ledger trailing loose pages behind them.",
      "characters": ["mara_the_cartographer", "glass_diver", "sleeping_tax_collector", "oracle_lamp"]
    },
    {
      "scene_number": 17,
      "caption": "The bridge groans as armored patrols close in.",
      "visual_description": "A long stone bridge over a misty chasm cracks under running feet; behind them, glints of plate armor advance through arched gateways.",
      "characters": ["mara_the_cartographer", "glass_diver", "sleeping_tax_collector", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 18,
      "caption": "They cross into the dawn beyond the ruined city.",
      "visual_description": "On the far side of the bridge, the group stands silhouetted against a pale sunrise; the tin fox looks back, the lamp's eye softening to gold, the official still snoring on Mara's shoulder.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp", "tin_fox", "sleeping_tax_collector"]
    }
  ]
}

